-- PostgreSQL 14+; Django-compatible demo schema, no COPY FROM stdin
-- Version 2: timestamps and identity IDs for Django CRUD
-- Демонстрационная БД продаж морепродуктов (PostgreSQL 14+)
-- 1000 товаров, 50000 продаж, 3000 поставок, 5 складов.
-- Все данные синтетические; цены в RUB/кг, количество в тоннах.
-- Выполнить: psql -X -v ON_ERROR_STOP=1 -d YOUR_DATABASE -f seafood_demo_django_rebuild.sql
-- ВНИМАНИЕ: пересоздаёт схему seafood_demo (не затрагивает другие схемы).
BEGIN;
DROP SCHEMA IF EXISTS seafood_demo CASCADE;
CREATE SCHEMA seafood_demo;
SET search_path TO seafood_demo, public;
CREATE TABLE categories (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, parent_id integer REFERENCES categories(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id integer NOT NULL REFERENCES categories(id), name text NOT NULL, origin_country text NOT NULL, package_kg numeric(6,2) NOT NULL CHECK(package_kg>0), cost_rub_kg numeric(12,2) NOT NULL CHECK(cost_rub_kg>=0), min_price_rub_kg numeric(12,2) NOT NULL CHECK(min_price_rub_kg>=cost_rub_kg), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE warehouses (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE inventory (product_id integer NOT NULL REFERENCES products(id), warehouse_id integer NOT NULL REFERENCES warehouses(id), quantity_t numeric(12,3) NOT NULL CHECK(quantity_t>=0), reserved_t numeric(12,3) NOT NULL CHECK(reserved_t>=0 AND reserved_t<=quantity_t), PRIMARY KEY(product_id,warehouse_id));
CREATE TABLE shipments (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id integer NOT NULL REFERENCES products(id), warehouse_id integer NOT NULL REFERENCES warehouses(id), quantity_t numeric(12,3) NOT NULL CHECK(quantity_t>0), reserved_t numeric(12,3) NOT NULL CHECK(reserved_t>=0 AND reserved_t<=quantity_t), shipped_on date NOT NULL, expected_on date NOT NULL CHECK(expected_on>=shipped_on), status text NOT NULL CHECK(status IN ('planned','in_transit','received')));
CREATE TABLE sales (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id integer NOT NULL REFERENCES products(id), warehouse_id integer NOT NULL REFERENCES warehouses(id), sold_on date NOT NULL, quantity_t numeric(12,3) NOT NULL CHECK(quantity_t>0), price_rub_kg numeric(12,2) NOT NULL CHECK(price_rub_kg>0));
-- 1 тонна = 1000 кг, сумма продажи = quantity_t * 1000 * price_rub_kg.













CREATE INDEX idx_categories_parent ON categories(parent_id);
CREATE INDEX idx_products_category ON products(category_id);
CREATE INDEX idx_sales_date_product ON sales(sold_on,product_id);
CREATE INDEX idx_sales_product_date ON sales(product_id,sold_on);
CREATE INDEX idx_shipments_status_expected ON shipments(status,expected_on);
CREATE INDEX idx_shipments_product ON shipments(product_id);
-- Витрина для таблицы продаж на дату среза. Измените дату в параметре as_of.
CREATE VIEW product_sales_report AS
WITH params AS (SELECT DATE '2026-11-18' AS as_of),
stock AS (SELECT product_id, SUM(quantity_t) AS stock_t, SUM(reserved_t) AS reserved_t FROM inventory GROUP BY product_id),
transit AS (SELECT s.product_id, SUM(s.quantity_t) AS transit_t, SUM(s.reserved_t) AS transit_reserved_t
  FROM shipments s CROSS JOIN params p WHERE s.shipped_on<=p.as_of AND s.expected_on>p.as_of AND s.status='in_transit' GROUP BY s.product_id),
agg AS (SELECT s.product_id,
 SUM(s.quantity_t) FILTER (WHERE s.sold_on BETWEEN p.as_of-INTERVAL '27 days' AND p.as_of-INTERVAL '21 days') AS week_minus_3_t,
 SUM(s.quantity_t) FILTER (WHERE s.sold_on BETWEEN p.as_of-INTERVAL '20 days' AND p.as_of-INTERVAL '14 days') AS week_minus_2_t,
 SUM(s.quantity_t) FILTER (WHERE s.sold_on BETWEEN p.as_of-INTERVAL '13 days' AND p.as_of-INTERVAL '7 days') AS week_minus_1_t,
 SUM(s.quantity_t) FILTER (WHERE s.sold_on BETWEEN p.as_of-INTERVAL '6 days' AND p.as_of) AS week_0_t,
 SUM(s.quantity_t*1000*s.price_rub_kg) FILTER (WHERE s.sold_on>=date_trunc('month',p.as_of)::date AND s.sold_on<=p.as_of) AS current_month_rub
 FROM sales s CROSS JOIN params p WHERE s.sold_on<=p.as_of GROUP BY s.product_id)
SELECT pr.id AS product_id, pr.category_id, pr.name AS product_name, pr.cost_rub_kg, pr.min_price_rub_kg,
 COALESCE(st.stock_t,0) AS stock_t, COALESCE(st.reserved_t,0) AS reserved_t,
 COALESCE(t.transit_t,0) AS transit_t, COALESCE(t.transit_reserved_t,0) AS transit_reserved_t,
 COALESCE(a.week_minus_3_t,0) AS week_minus_3_t, COALESCE(a.week_minus_2_t,0) AS week_minus_2_t,
 COALESCE(a.week_minus_1_t,0) AS week_minus_1_t, COALESCE(a.week_0_t,0) AS week_0_t,
 ROUND((COALESCE(a.week_minus_3_t,0)+COALESCE(a.week_minus_2_t,0)+COALESCE(a.week_minus_1_t,0))/3,3) AS avg_3_weeks_t,
 COALESCE(a.current_month_rub,0) AS current_month_rub
FROM products pr LEFT JOIN stock st ON st.product_id=pr.id LEFT JOIN transit t ON t.product_id=pr.id LEFT JOIN agg a ON a.product_id=pr.id;
-- Пример: SELECT * FROM seafood_demo.product_sales_report LIMIT 20;
-- Пример: SELECT COUNT(*) FROM seafood_demo.sales; -- 50000
-- Sequence counters must follow explicitly inserted seed IDs.
SELECT setval(pg_get_serial_sequence('seafood_demo.categories', 'id'), (SELECT MAX(id) FROM categories));
SELECT setval(pg_get_serial_sequence('seafood_demo.products', 'id'), (SELECT MAX(id) FROM products));
SELECT setval(pg_get_serial_sequence('seafood_demo.warehouses', 'id'), (SELECT MAX(id) FROM warehouses));
SELECT setval(pg_get_serial_sequence('seafood_demo.shipments', 'id'), (SELECT MAX(id) FROM shipments));
SELECT setval(pg_get_serial_sequence('seafood_demo.sales', 'id'), (SELECT MAX(id) FROM sales));

-- Keep updated_at accurate for writes from Django and direct SQL.
CREATE FUNCTION seafood_demo.touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;
CREATE TRIGGER categories_touch_updated_at BEFORE UPDATE ON categories
FOR EACH ROW EXECUTE FUNCTION seafood_demo.touch_updated_at();
CREATE TRIGGER products_touch_updated_at BEFORE UPDATE ON products
FOR EACH ROW EXECUTE FUNCTION seafood_demo.touch_updated_at();

CREATE INDEX idx_categories_parent_id ON categories(parent_id);
CREATE INDEX idx_products_category_id ON products(category_id);
CREATE INDEX idx_sales_product_date ON sales(product_id, sold_on);
CREATE INDEX idx_sales_warehouse_id ON sales(warehouse_id);
CREATE INDEX idx_shipments_product_status ON shipments(product_id, status);

COMMIT;
ANALYZE seafood_demo.categories;
ANALYZE seafood_demo.products;
ANALYZE seafood_demo.inventory;
ANALYZE seafood_demo.shipments;
ANALYZE seafood_demo.sales;
